# Multi-stage Dockerfile: compile fat, ship slim
FROM golang:1.22 AS build
WORKDIR /app
COPY go.mod go.sum ./
RUN go mod download        # slow-changing: cached
COPY . .                   # fast-changing: last
RUN go build -o server .

FROM gcr.io/distroless/static
COPY --from=build /app/server /server
ENTRYPOINT ["/server"]

# Jenkinsfile stage skeleton with a security gate
pipeline {
  agent any
  stages {
    stage('lint')   { steps { sh 'make lint' } }
    stage('test')   { steps { sh 'make test' } }
    stage('build')  { steps { sh 'docker build -t app:${BUILD_ID} .' } }
    stage('scan')   { steps { sh 'trivy image app:${BUILD_ID}' } } // gate: fail the build
    stage('push')   { steps { sh 'docker push app:${BUILD_ID}' } }
    stage('deploy') { steps { sh 'kubectl set image deploy/app app=app:${BUILD_ID}' } }
  }
}

# Reference stack sketch: VPC + ALB + ASG + RDS (composable modules)
module "vpc" {
  source = "./modules/vpc"   # multi-AZ subnets, NAT, route tables
}
module "web" {
  source     = "./modules/alb-asg"
  subnet_ids = module.vpc.public_subnet_ids  # ALB across AZs
}
module "db" {
  source          = "./modules/rds"
  multi_az        = true                     # resilience unit = AZ
  subnet_ids      = module.vpc.private_subnet_ids
}
# Decouple tiers: slowdowns become queue depth
resource "aws_sqs_queue" "orders" {
  name = "orders"
}

# Athena forensics over the org CloudTrail lake (no SIEM budget needed)
SELECT eventtime, useridentity.arn, eventname, sourceipaddress
FROM cloudtrail_logs
WHERE eventname = 'ConsoleLogin'
  AND eventtime > date_add('day', -30, current_date)
ORDER BY eventtime DESC
LIMIT 100;

# Preventive guardrail: deny unencrypted S3 org-wide (SCP)
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "DenyUnencryptedS3",
    "Effect": "Deny",
    "Action": "s3:PutObject",
    "Resource": "*",
    "Condition": { "StringNotEquals": { "s3:x-amz-server-side-encryption": "aws:kms" } }
  }]
}

